declare module "@tiptap/core" {
  interface Commands<ReturnType> {
    mermaid: {
      setMermaid: (attributes?: Partial<MermaidAttributes>) => ReturnType;
    };
  }
}

const FENCE_OPEN = /^ {0,3}(`{3,}|~{3,})[ \t]*mermaid(?:[ \t][^\n]*)?(?:\n|$)/;
const FENCE_OPEN_ANYWHERE = new RegExp(FENCE_OPEN.source, "m");

const longestRun = (value: string, char: string) => {
  let longest = 0;
  for (const run of value.match(new RegExp(`\\${char}+`, "g")) ?? []) {
    longest = Math.max(longest, run.length);
  }
  return longest;
};

export const Mermaid = Node.create<MermaidOptions>({
  addAttributes() {
    return {
      value: {
        default: null,
        parseHTML: (element) => element.textContent || null,
        rendered: false,
      },
    };
  },

  addCommands() {
    return {
      setMermaid:
        (attributes) =>
        ({ commands }) =>
          commands.insertContent({
            attrs: { value: attributes?.value ?? null },
            type: this.name,
          }),
    };
  },

  addNodeView() {
    return ReactNodeViewRenderer(MermaidView, {
      stopEvent: ({ event }) =>
        event.target instanceof Element &&
        event.target.closest(".ext-mermaid-frame") !== null,
    });
  },

  addOptions() {
    return {
      HTMLAttributes: {},
    };
  },

  atom: true,
  group: "block",

  markdownTokenName: "mermaid",

  markdownTokenizer: {
    level: "block",
    name: "mermaid",
    start: (src: string) => {
      const match = FENCE_OPEN_ANYWHERE.exec(src);
      return match ? match.index : -1;
    },
    tokenize: (src: string) => {
      const open = FENCE_OPEN.exec(src);
      const fence = open?.[1];
      if (!open || !fence) {
        return;
      }
      const afterOpen = src.slice(open[0].length);
      const close = new RegExp(
        `^ {0,3}\\${fence[0]}{${fence.length},}[ \\t]*$`,
        "m"
      ).exec(afterOpen);
      const body = close ? afterOpen.slice(0, close.index) : afterOpen;
      let rawLength = close
        ? open[0].length + close.index + close[0].length
        : src.length;
      if (src[rawLength] === "\n") {
        rawLength += 1;
      }
      return {
        raw: src.slice(0, rawLength),
        text: body.endsWith("\n") ? body.slice(0, -1) : body,
        type: "mermaid",
      };
    },
  },

  name: "mermaid",

  parseHTML() {
    return [{ tag: 'div[data-type="mermaid"]' }];
  },

  parseMarkdown: (token, helpers) =>
    helpers.createNode("mermaid", { value: token.text || null }),

  renderHTML({ HTMLAttributes, node }) {
    return [
      "div",
      mergeAttributes(this.options.HTMLAttributes, HTMLAttributes, {
        "data-type": "mermaid",
      }),
      ["pre", ["code", { class: "language-mermaid" }, node.attrs.value ?? ""]],
    ];
  },

  renderMarkdown: (node) => {
    const value = (node.attrs?.value as string | null) ?? "";
    const fence = "`".repeat(Math.max(3, longestRun(value, "`") + 1));
    return value
      ? `${fence}mermaid\n${value}\n${fence}`
      : `${fence}mermaid\n${fence}`;
  },
});

"use client";

import { useEffect, useRef } from "react";
import type { ReactNode } from "react";

import { cn } from "../ui/utils";
import { renderCached, useMermaidTheme } from "./render";
import type { MermaidTheme } from "./render";

const SOURCE_SELECTOR = 'div[data-type="mermaid"] > pre > code';

const SVG_CLASS =
  "ext-mermaid-svg flex justify-center overflow-auto p-4 [&_svg]:h-auto [&_svg]:max-w-full";

const draw = async (
  block: HTMLElement,
  pre: HTMLElement,
  key: string,
  source: string,
  theme: MermaidTheme
) => {
  let output = block.querySelector<HTMLElement>(":scope > .ext-mermaid-svg");
  try {
    const svg = await renderCached(source, theme);
    if (block.dataset.mermaidKey !== key) {
      return;
    }
    if (!output) {
      output = document.createElement("div");
      output.className = SVG_CLASS;
      block.append(output);
    }
    output.innerHTML = svg;
    pre.hidden = true;
  } catch {
    output?.remove();
    pre.hidden = false;
  }
};

const drawAll = (root: HTMLElement, theme: MermaidTheme) => {
  for (const code of root.querySelectorAll<HTMLElement>(SOURCE_SELECTOR)) {
    const pre = code.parentElement;
    const block = pre?.parentElement;
    const source = code.textContent?.trim();
    if (!pre || !block || !source) {
      continue;
    }
    const key = `${theme}\n${source}`;
    if (block.dataset.mermaidKey === key) {
      continue;
    }
    block.dataset.mermaidKey = key;
    draw(block, pre, key, source, theme);
  }
};

export interface MermaidDiagramsProps {
  children: ReactNode;
  className?: string;
}

export const MermaidDiagrams = ({
  children,
  className,
}: MermaidDiagramsProps) => {
  const ref = useRef<HTMLDivElement>(null);
  const theme = useMermaidTheme();

  useEffect(() => {
    const root = ref.current;
    if (!root) {
      return;
    }
    drawAll(root, theme);
    const observer = new MutationObserver(() => drawAll(root, theme));
    observer.observe(root, {
      characterData: true,
      childList: true,
      subtree: true,
    });
    return () => observer.disconnect();
  }, [theme]);

  return (
    <div ref={ref} className={cn("ext-mermaid-diagrams", className)}>
      {children}
    </div>
  );
};

"use client";

import { useEffect, useRef, useState } from "react";

import { useToolbar } from "../core/context";
import { cn } from "../ui/utils";
import { cache, renderCached, useMermaidTheme } from "./render";

const RENDER_DELAY = 300;

interface RenderState {
  error?: string;
  key: string;
  svg?: string;
}

export interface MermaidPreviewProps {
  className?: string;
  value: string | null;
}

export const MermaidPreview = ({ className, value }: MermaidPreviewProps) => {
  const source = value?.trim() ?? "";
  const theme = useMermaidTheme();
  const { labels } = useToolbar();
  const key = `${theme}\n${source}`;
  const [state, setState] = useState<RenderState>(() => ({
    key,
    svg: cache.get(key),
  }));
  const rendered = useRef(Boolean(state.svg));

  useEffect(() => {
    if (!source) {
      return;
    }
    if (cache.has(key)) {
      rendered.current = true;
      return;
    }
    let cancelled = false;
    const timer = setTimeout(
      async () => {
        try {
          const svg = await renderCached(source, theme);
          if (!cancelled) {
            rendered.current = true;
            setState({ key, svg });
          }
        } catch (error) {
          if (!cancelled) {
            setState((current) => ({
              error: error instanceof Error ? error.message : "",
              key,
              svg: current.svg,
            }));
          }
        }
      },
      rendered.current ? RENDER_DELAY : 0
    );
    return () => {
      cancelled = true;
      clearTimeout(timer);
    };
  }, [key, source, theme]);

  if (!source) {
    return (
      <div
        className={cn(
          "ext-mermaid-empty flex min-h-32 items-center justify-center p-6 text-center text-xs text-muted-foreground",
          className
        )}
      >
        {labels.emptyDiagram}
      </div>
    );
  }

  const failure = state.key === key ? state.error : undefined;
  const error = failure === "" ? labels.diagramError : failure;
  const svg = cache.get(key) ?? state.svg;

  if (!svg) {
    return (
      <div className={cn("ext-mermaid-fallback", className)}>
        <output
          className={cn(
            "block px-4 pt-3 font-mono text-xs whitespace-pre-wrap",
            error ? "text-destructive" : "text-muted-foreground"
          )}
        >
          {error ?? labels.renderingDiagram}
        </output>
        <pre className="m-0 overflow-x-auto bg-transparent p-4 font-mono text-xs">
          <code>{source}</code>
        </pre>
      </div>
    );
  }

  return (
    <div className={cn("ext-mermaid-preview flex flex-col", className)}>
      {error && (
        <output className="ext-mermaid-error block px-4 pt-3 font-mono text-xs whitespace-pre-wrap text-destructive">
          {error}
        </output>
      )}
      <div
        className={cn(
          "ext-mermaid-svg flex justify-center overflow-auto p-4 [&_svg]:h-auto [&_svg]:max-w-full",
          error && "opacity-50"
        )}
        dangerouslySetInnerHTML={{ __html: svg }}
      />
    </div>
  );
};

import { useSyncExternalStore } from "react";

export type MermaidTheme = "dark" | "default";

const CACHE_LIMIT = 100;

export const cache = new Map<string, string>();
let queue: Promise<unknown> = Promise.resolve();
let renderCount = 0;

const settled = async (promise: Promise<unknown>) => {
  try {
    return await promise;
  } catch (error) {
    return error;
  }
};

const renderDiagram = (source: string, theme: MermaidTheme) => {
  const previous = queue;
  const task = (async () => {
    await previous;
    const { default: mermaid } = await import("mermaid");
    mermaid.initialize({
      securityLevel: "strict",
      startOnLoad: false,
      suppressErrorRendering: true,
      theme,
    });
    renderCount += 1;
    const { svg } = await mermaid.render(`ext-mermaid-${renderCount}`, source);
    return svg;
  })();
  queue = settled(task);
  return task;
};

export const remember = (key: string, svg: string) => {
  cache.delete(key);
  cache.set(key, svg);
  if (cache.size > CACHE_LIMIT) {
    const oldest = cache.keys().next().value;
    if (oldest !== undefined) {
      cache.delete(oldest);
    }
  }
};

const subscribeToTheme = (onChange: () => void) => {
  const observer = new MutationObserver(onChange);
  observer.observe(document.documentElement, {
    attributeFilter: ["class"],
    attributes: true,
  });
  return () => observer.disconnect();
};

export const useMermaidTheme = (): MermaidTheme =>
  useSyncExternalStore(
    subscribeToTheme,
    () =>
      document.documentElement.classList.contains("dark") ? "dark" : "default",
    () => "default"
  );

export const renderCached = async (source: string, theme: MermaidTheme) => {
  const key = `${theme}\n${source}`;
  const cached = cache.get(key);
  if (cached) {
    return cached;
  }
  const svg = await renderDiagram(source, theme);
  remember(key, svg);
  return svg;
};

